class UserProfile {
  public id: string;
  public name: string;
  public email: string;
  constructor(id: string, name: string, email: string) {
    this.id = id;
    this.name = name;
    this.email = email;
  }
  getDisplayName() { return this.name; }
}

class Invoice {
  private id: string;
  private items: { price: number; qty: number }[];
  constructor(id: string, items: { price: number; qty: number }[]) {
    this.id = id;
    this.items = items;
  }
  total() { return this.items.reduce((s, i) => s + i.price * i.qty, 0); }
}

