class Customer {
  private balance: number;
  constructor(balance = 0) { this.balance = balance; }
  charge(amount: number) {
    if (amount + this.balance > 10000) throw new Error('limit exceeded');
    this.balance += amount;
  }
}

// Version B
class Customer {
  public balance: number;
  constructor(balance = 0) { this.balance = balance; }
}
class CustomerService {
  charge(customer: Customer, amount: number) {
    if (amount + customer.balance > 10000) throw new Error('limit exceeded');
    customer.balance += amount;
  }
}
